(() => {
  const $=id=>document.getElementById(id);
  const api=async(path,options={})=>{const response=await fetch(path,{cache:'no-store',headers:{accept:'application/json',...(options.body?{'content-type':'application/json'}:{})},...options,body:options.body?JSON.stringify(options.body):undefined});const text=await response.text();let data={};try{data=JSON.parse(text||'{}')}catch{data={ok:false,error:text||'Invalid response'}}if(response.status===401){location.href='/member-login.html?return=%2Fbilling-dashboard.html';throw new Error('Authentication required')}if(!response.ok||data.ok===false)throw new Error(data.error||'Billing request failed');return data};
  const title=value=>String(value||'').replaceAll('_',' ').replace(/\b\w/g,char=>char.toUpperCase());
  function status(message,type=''){const node=$('billing-status');node.className='status '+type;node.textContent=message}
  function date(value){return value?new Date(value).toLocaleString():'Not available'}
  function render(data){const subscription=data.subscription;$('billing-content').hidden=false;if(!subscription){$('no-subscription').hidden=false;$('subscription-panel').hidden=true;return}$('no-subscription').hidden=true;$('subscription-panel').hidden=false;$('billing-tier').textContent=title(subscription.tier);$('billing-state').textContent=title(subscription.billing_state||subscription.provider_status);$('billing-environment').textContent=title(subscription.environment||data.environment);$('billing-access').textContent=data.paidAccess?'Paid access active':'Paid access not active';$('billing-access').className=data.paidAccess?'good':'warning';$('billing-next').textContent=date(subscription.next_billing_at||subscription.current_period_end);$('billing-last').textContent=date(subscription.last_payment_at);$('billing-failures').textContent=String(subscription.payment_failure_count||0);$('billing-holds').textContent=[subscription.refund_hold?'Refund hold':'',subscription.reversal_hold?'Reversal hold':''].filter(Boolean).join(' · ')||'None';$('cancel-button').disabled=['cancelled','expired','refund_hold','reversal_hold'].includes(subscription.billing_state)}
  async function load(){try{status('Loading verified PayPal billing state…');const data=await api('/api/paypal/subscription');render(data);status('Billing state is current.','good')}catch(error){status(error.message||'Billing dashboard failed.','danger')}}
  $('cancel-button').addEventListener('click',async()=>{if(!confirm('Cancel this PayPal subscription? Access will follow the verified paid-period state returned by the server.'))return;try{status('Cancelling through PayPal…');const data=await api('/api/paypal/subscription/cancel',{method:'POST',body:{}});status(data.paidAccess?'Cancelled. Access remains until the verified paid period ends.':'Cancelled. Paid access is no longer active.','warning');await load()}catch(error){status(error.message,'danger')}});
  load();
})();
